export function getRandomQuestion(categoryId, usedIndices = [], lang = "en") {
  const pool = questions[categoryId];
  if (!pool) return null;
  const available = pool
    .map((q, i) => ({ q, i }))
    .filter(({ i }) => !usedIndices.includes(i));
  const entry = available.length === 0
    ? pool[Math.floor(Math.random() * pool.length)]
    : available[Math.floor(Math.random() * available.length)];
  const idx = available.length === 0 ? -1 : entry.i;
  const raw = available.length === 0 ? entry : entry.q;
  // raw is { en, id } object
  const question = typeof raw === "object" ? (raw[lang] ?? raw.en) : raw;
  return { question, raw, index: idx };
}
